StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Analog Input ADAM 4017/4117                                                                                                                                                                                                                                                             
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                  
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-02-15		William Veim				Initial release
//	1.1.0				2025-03-19		William Veim				Removed input for SMS process value
//	2.0.0				2025-04-17		William Veim				Rework - Moved modbus configuration to FB 
//
//===============================================================================================================================
//
//		FUNKSJONALITET:
//		*Analog input (signal value) 
//		*Scaling of raw value to signal value
//		*Excecution of analog input logic
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
Inp_Request[Cfg_Request_StartPos].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos].NodeAdr := Cfg_NodeAdr;
Inp_Request[Cfg_Request_StartPos].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos;
Inp_Request[Cfg_Request_StartPos].Read.StartAddressRemote := 0+Cfg_ChannelNumber;
Inp_Request[Cfg_Request_StartPos].Read.Count := 1; 

Inp_Request[Cfg_Request_StartPos+1].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+1].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+1].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+1;
Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressRemote := 200+Cfg_ChannelNumber;
Inp_Request[Cfg_Request_StartPos+1].Read.Count := 1;

 (*************************************************************************
 *	PARSING DATA
 *************************************************************************)
Wrk_CommStatus:=TRUE;

IF (Inp_Request[Cfg_Request_StartPos].Status.Error AND NOT Inp_Request[Cfg_Request_StartPos].Status.Success) 
	AND (Inp_Request[Cfg_Request_StartPos+1].Status.Error AND NOT Inp_Request[Cfg_Request_StartPos+1].Status.Success) THEN
	
	Wrk_CommStatus:=FALSE;
END_IF;

Wrk_RawValue:=					WORD_TO_INT(Inp_HoldingRegister[Cfg_HoldingReg_StartPos]);
Wrk_ChannelTypeCode:=	Inp_HoldingRegister[Cfg_HoldingReg_StartPos+1];

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_AnalogValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
FB_AnalogInput_Logic.Cfg_ValueType:=FALSE; //INPUT VALUE TO LOGIC BLOCK IS SIGNAL VALUE
FB_AnalogInput_Logic.Cfg_CalibrationEnable:=TRUE;

IF  NOT Ext_AnalogValue.INT_Data.Initialise THEN
	
	//Common parameters are initialised in logic block
	
	//State config
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Quality:=0; //Signal value out of range = Diagnostic
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Alarm:=TRUE; //Output module fault = Alarm
	
	//Initialise set true in logic block
	
END_IF;

(*************************************************************************
 *	BLOCK SPESIFIC PARAMETERS
 *************************************************************************)
 
FB_AnalogInput_Logic.Cfg_ValueType:=FALSE; //INPUT VALUE TO LOGIC BLOCK IS SIGNAL VALUE

HE_ADAM_AD_Module(Cfg_ADAM_TypeCode:=WORD_TO_UINT(Wrk_ChannelTypeCode), 
										Out_SignalValue_Y0=>Wrk_SignalValue_Y0, 
										Out_SignalValue_Y1=>Wrk_SignalValue_Y1,
										Out_SignalValue_Min=>Wrk_SignalValue_Min, 
										Out_SignalValue_Max=>Wrk_SignalValue_Max, 
										Out_SignalValue_Unit=>Wrk_SignalValue_Unit, 
										Out_RawValue_X0=>Wrk_RawValue_X0, 
										Out_RawValue_X1=>Wrk_RawValue_X1, 
										Out_RawValue_Min=>Wrk_RawValue_Min, 
										Out_RawValue_Max=>Wrk_RawValue_Max);

(*************************************************************************
 *	UPDATE INPUT PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_AnalogInput_Logic.Inp_AlmSuppressDesc:=		Inp_AlmSuppressDesc;
FB_AnalogInput_Logic.Inp_ModuleFault:=				Wrk_CommStatus;
FB_AnalogInput_Logic.Inp_LoopBreak:=					FB_AnalogInput_Logic.Inp_Value<1; //Input value lower than 1mV

FB_AnalogInput_Logic.Inp_Value:=							ScaleTrans(SclIn:=Wrk_RawValue, 
																										X0:=Wrk_RawValue_X0, 
																										Y0:=Wrk_SignalValue_Y0, 
																										X1:=Wrk_RawValue_X1, 
																										Y1:=Wrk_SignalValue_Y1);
																									
FB_AnalogInput_Logic.Inp_Value:=							LIMIT(MN:= Wrk_SignalValue_Min, 
																								In:=FB_AnalogInput_Logic.Inp_Value, 
																								MX:=Wrk_SignalValue_Max);

(*************************************************************************
 *	UPDATE CONFIG PARAMETERS
 *************************************************************************)
 
FB_AnalogInput_Logic.Cfg_SignalValue_Y0:=							REAL_TO_UINT(Wrk_SignalValue_Y0);
FB_AnalogInput_Logic.Cfg_SignalValue_Y1:=							REAL_TO_UINT(Wrk_SignalValue_Y1);
FB_AnalogInput_Logic.Cfg_SignalValue_Unit:=						Wrk_SignalValue_Unit;
FB_AnalogInput_Logic.Cfg_ControlCabinet:=							Cfg_ConnCabinet;
FB_AnalogInput_Logic.Cfg_ControllerTAG:=							Cfg_ControllerName;
FB_AnalogInput_Logic.Cfg_ProcessTAG:=								Cfg_ProcessTAG;

(*************************************************************************
 *	STATISTICS
 * (Asuming sensor has been changed, if loop break over a period)
 *************************************************************************)

TON_LoopBreak(In:=TON_SignalValueFault.Q AND NOT Wrk_CommStatus, PT:=TIME#2h);

FB_AnalogInput_Logic.Inp_RstOperatingTime:=TON_LoopBreak.Q;

(*************************************************************************
 *	UPDATING STATE CONTROL PARAMTERS
 *************************************************************************)

 //STATE 1 - Locked to "Critical high limit"
 //STATE 2 - Locked to "Pre high limit"
 //STATE 3 - Locked to "Pre low limit"
 //STATE 4 - Locked to "Critical low limit"
 //STATE 5 - Locked to "Process value out of range"
 //STATE 6 - Locked to "Input module fault"
 //STATE 7 - Locked to "Value stuck"
 //STATE 8 - Locked to "Calibration fault"
 //STATE 9 - Locked to "Unstable value"

TON_SignalValueFault(In:=FB_AnalogInput_Logic.Inp_Value < 1, //Signal value lower than 1mV
									PT:=TIME#10s, 
									Q=>Wrk_SignalValueFault);
 
FB_AnalogInput_Logic.Cfg_State10_InUse:= 	TRUE;
FB_AnalogInput_Logic.Inp_State10_Desc:=		'Signal value out of range';
FB_AnalogInput_Logic.Inp_State10_State:= 	Wrk_SignalValueFault;

FB_AnalogInput_Logic.Cfg_State11_InUse:= 	FALSE;
FB_AnalogInput_Logic.Inp_State11_Desc:=		'NOT IN USE';
FB_AnalogInput_Logic.Inp_State11_State:=		FALSE;

FB_AnalogInput_Logic.Cfg_State12_InUse:= 	FALSE;
FB_AnalogInput_Logic.Inp_State12_Desc:=		'NOT IN USE';
FB_AnalogInput_Logic.Inp_State12_State:=		FALSE;

(*************************************************************************
 *	EXCECUTING LOGICK BLOCK
 *************************************************************************)
 
FB_AnalogInput_Logic(ENS:=TRUE, 
										Ext_AnalogValue:=	Ext_AnalogValue, 
										Int_Alarm:=				Int_Alarm);

(*************************************************************************
 *	UPDATING FB OUTPUT
 *************************************************************************)
 
Sts_Alarm:= 								FB_AnalogInput_Logic.Sts_AlarmTriggered;
Out_ProcessValue:= 				Ext_AnalogValue.EXT_Operator.ProcessValue;
Out_ProcessValue_Percent := 	Ext_AnalogValue.EXT_Operator.ProcessValue_Percent;
